import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.BbQUUm7J.js";const k=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1794859264000}'),n={name:"guide/getting-started.md"};function l(r,e,d,o,h,p){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>FurlPay CLI (<code>@furlpay/cli</code>) is a high-performance terminal execution layer for stablecoin payments, tokenized securities, decentralized perps and autonomous agent trading. It is <strong>non-custodial</strong>: private keys are generated, stored and used locally — the CLI never transmits key material anywhere.</p><div class="warning custom-block"><p class="custom-block-title">What is live vs. simulated</p><p>Every execution surface in this CLI is <strong>labeled at runtime</strong>. Hyperliquid perp execution, HLP vault transfers, transaction verification and the testnet faucet are live. Stellar SDEX order flow, Soroban swaps, x402 settlement and MCP balance queries are <strong>clearly-labeled local simulations</strong> in this build. The <a href="/furlpay-cli/reference/honesty-matrix">Honesty Matrix</a> is the authoritative table.</p></div><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li><strong>Node.js ≥ 22.19.0</strong> (npm ships with it)</li><li>Linux, macOS, or Windows — no administrator/root privileges needed</li><li>A terminal (any)</li></ul><p>Check your version:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @furlpay/cli</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">furlpay</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>Other vectors — curl/PowerShell one-liners, <code>npx</code>, offline tarballs with checksums and SBOMs, and self-update — are covered in <a href="/furlpay-cli/guide/installation">Installation</a>.</p><h2 id="your-first-five-commands" tabindex="-1">Your first five commands <a class="header-anchor" href="#your-first-five-commands" aria-label="Permalink to &quot;Your first five commands&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Install diagnostics: install method, registry, config, connectivity</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">furlpay</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Look at the local configuration and validate its security bounds</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">furlpay</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Live market data from Hyperliquid validators</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">furlpay</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hyperliquid</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">furlpay</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> market</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BTC</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 4. Verify a real transaction on Stellar mainnet (a documented example hash)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">furlpay</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 37ccb558c42b9386c91a7895e54d3da92ddf3e09cb46d5119be0eb4cf49679e4</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mainnet</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 5. The offline reference preview of a payment — zero network calls, zero execution</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">furlpay</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pay</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --demo</span></span></code></pre></div><h2 id="mental-model" tabindex="-1">Mental model <a class="header-anchor" href="#mental-model" aria-label="Permalink to &quot;Mental model&quot;">​</a></h2><p>The CLI is split into two planes that never share secrets:</p><table tabindex="0"><thead><tr><th>Plane</th><th>What it does</th><th>What it holds</th></tr></thead><tbody><tr><td><strong>Identity</strong> (<code>furlpay login</code>, <code>whoami</code>)</td><td>Authenticates you to the web dashboard, reads balances and history</td><td>A read-only session cookie</td></tr><tr><td><strong>Execution</strong> (trading, payments, wallets)</td><td>Signs orders and transfers <strong>locally</strong></td><td>Private keys in hardware, extensions, or the encrypted keystore</td></tr></tbody></table><p>A stolen web session cannot move funds; a stolen exchange API key cannot withdraw. See the <a href="/furlpay-cli/reference/security">Security Model</a>.</p><h2 id="where-your-data-lives" tabindex="-1">Where your data lives <a class="header-anchor" href="#where-your-data-lives" aria-label="Permalink to &quot;Where your data lives&quot;">​</a></h2><p>Everything is under <code>~/.furlpay/</code>:</p><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>config.json</code></td><td>Environment selection, API endpoints, session cookies</td></tr><tr><td><code>keystore.enc</code></td><td>PBKDF2 + AES-256-GCM encrypted wallet material</td></tr><tr><td><code>escrows.json</code></td><td>The local escrow ledger (state machine + audit log)</td></tr><tr><td><code>agent-policies/</code></td><td>Autonomous agent spending policies (atomic, file-locked)</td></tr></tbody></table><p>On POSIX the directory is <code>0700</code> and files <code>0600</code>; on Windows secrets are DPAPI-sealed.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/furlpay-cli/guide/authentication">Authenticate</a> — <code>furlpay login --device</code></li><li><a href="/furlpay-cli/guide/payments">Make a payment</a> — <code>furlpay pay &#39;@vendor&#39; 250 USD</code></li><li><a href="/furlpay-cli/guide/hyperliquid">Trade perps with guardrails</a> — <code>furlpay trading limits --max-leverage 3</code></li><li><a href="/furlpay-cli/guide/agents">Give an AI agent a spending mandate</a> — <code>furlpay wallet agent-keygen</code></li></ul>`,22)])])}const u=a(n,[["render",l]]);export{k as __pageData,u as default};
